'use strict';
const $ = (s, root=document) => root.querySelector(s);
const $$ = (s, root=document) => [...root.querySelectorAll(s)];
const MONTHS=['January','February','March','April','May','June','July','August','September','October','November','December'];
const SHORT=MONTHS.map(m=>m.slice(0,3));
const THEMES={
  explorer:{name:'Explorer',eyebrow:'YOUR NEXT EXPEDITION',heading:'Find your next <em>great escape.</em>',sub:'Choose a month. Discover a world worth exploring.',mapLabel:'WORLD EXPLORATION / SEASONAL CONDITIONS',canadaDeck:'Big skies. Wild places. Your next chapter.',image:'./assets/explorer-canada.png',imageLabel:'THE CANADIAN ROCKIES',imageCredit:'Canadian Rockies · conceptual illustration'},
  brochure:{name:'Travel Bureau',eyebrow:'THE WHEN TO GO TRAVEL BUREAU',heading:'A world of <em>good timing.</em>',sub:'Every place has its season. Find yours.',mapLabel:'A TRAVELLER’S MAP OF THE WORLD',canadaDeck:'A grand adventure, in every season.',image:'./assets/brochure-canada.png',imageLabel:'GREETINGS FROM CANADA',imageCredit:'Canadian Rockies · conceptual illustration'},
  atlas:{name:'Field Atlas',eyebrow:'THE SEASONAL ATLAS',heading:'Right place. <em>Right time.</em>',sub:'A clearer view of when to go, anywhere on earth.',mapLabel:'WORLD / MONTHLY WEATHER COMFORT',canadaDeck:'A country of extraordinary contrasts.',image:'https://upload.wikimedia.org/wikipedia/commons/f/ff/Calm_waters_between_mountains_%28Unsplash%29.jpg',imageLabel:'MORAINE LAKE, ALBERTA',imageCredit:'Moraine Lake · Ezra Jeffrey / CC0'}
};
const q = new URLSearchParams(location.search);
const state={theme:THEMES[q.get('theme')]?q.get('theme'):'explorer',month:q.has('month')?Math.max(0,Math.min(11,(Number(q.get('month'))||1)-1)):6,iso:Number(q.get('country'))||124,page:location.hash==='#canada'?'canada':'map',view:'map',tilt:true};
let data, byIso, mapBox={x:0,y:10,w:1200,h:530};
const esc=s=>String(s).replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
const color=key=>`var(--${key})`;
const selected=()=>byIso.get(state.iso)||byIso.get(124);
const swatch=key=>`<i class="swatch" style="--swatch:${color(key)}"></i>`;
const climate=(rec=selected(),m=state.month)=>rec.months[m];
const project=(lon,lat)=>[(lon+180)/360*1200,(90-lat)/180*600];
const compass=`<svg viewBox="0 0 36 36" aria-hidden="true"><circle cx="18" cy="18" r="13"/><path d="m18 3 5 15-5 15-5-15zM3 18h30M18 3v30"/></svg>`;

function syncURL(){const url=new URL(location.href);url.searchParams.set('theme',state.theme);url.searchParams.set('month',String(state.month+1));url.searchParams.set('country',String(state.iso));url.hash=state.page==='canada'?'canada':'map';history.replaceState(null,'',url);}
function announce(text){$('#announcement').textContent=text;}
function setTheme(theme){if(!THEMES[theme])return;state.theme=theme;render();announce(`${THEMES[theme].name} design selected.`);}
function render(){document.documentElement.dataset.theme=state.theme;$$('.design-options button').forEach(b=>b.setAttribute('aria-pressed',String(b.dataset.theme===state.theme)));$('.design-label span').textContent=`/ 0${Object.keys(THEMES).indexOf(state.theme)+1}`;$$('.page-nav a').forEach(a=>{if(a.dataset.page===state.page)a.setAttribute('aria-current','page');else a.removeAttribute('aria-current');});document.title=`${state.page==='canada'?'Canada':'World map'} | ${THEMES[state.theme].name} | When To Go`;$('#app').innerHTML=state.page==='canada'?guideHTML():mapHTML();syncURL();if(state.page==='map')wireMap();else wireGuide();wireImages();}
function wireImages(){$$('img[data-travel-image]').forEach(img=>img.addEventListener('error',()=>{if(img.dataset.fallback)return;img.dataset.fallback='true';img.src='./assets/brochure-canada.png';img.alt='Illustration of an alpine lake in the Canadian Rockies';const figure=img.closest('figure');if(figure)$('figcaption',figure).textContent='Canadian Rockies · illustration';const label=img.parentElement.querySelector('.photo-label');if(label)label.textContent='THE CANADIAN ROCKIES';}));}
function setMonth(month){state.month=month;syncURL();if(state.page==='map'){paintMap();$('#destination').innerHTML=destinationHTML();wireDestination();wireImages();$$('.month-buttons button').forEach(b=>b.setAttribute('aria-pressed',String(+b.dataset.month===month)));$('.timeline-intro strong').textContent=`${MONTHS[month]} looks good on you.`;if(state.view==='grid')$('#country-grid-body').innerHTML=gridRows();}else{$$('#year-chart button').forEach(b=>{b.classList.toggle('active',+b.dataset.month===month);b.setAttribute('aria-pressed',String(+b.dataset.month===month));});$('#month-detail').innerHTML=monthDetailHTML();}announce(`${MONTHS[month]} selected. ${selected().name}: ${climate().band.label}, ${climate().score} out of 100.`);}
function setCountry(iso){if(!byIso.has(iso))return;state.iso=iso;syncURL();$('#destination').innerHTML=destinationHTML();wireDestination();wireImages();paintMap();announce(`${selected().name} selected. ${climate().band.label} weather in ${MONTHS[state.month]}.`);}
function legendHTML(){return `<div class="legend"><strong>Weather comfort</strong>${['avoid','fair','good','great','ideal'].map(k=>`<span>${swatch(k)}${k[0].toUpperCase()+k.slice(1)}</span>`).join('')}<span class="legend-help" title="A 0 to 100 weather comfort score for one representative city per country. Climate averages, not a forecast.">How we rate</span></div>`;}
function timelineHTML(){return `<section class="timeline" aria-label="Choose a month"><div class="timeline-intro"><strong>${MONTHS[state.month]} looks good on you.</strong><span>Find your season</span></div><div class="month-buttons">${SHORT.map((m,i)=>`<button data-month="${i}" aria-label="${MONTHS[i]}" aria-pressed="${i===state.month}">${m}<span class="month-dot" aria-hidden="true"></span></button>`).join('')}</div></section>`;}
function statsHTML(rec){return `<div class="mini-stats"><div><strong>${rec.hi[state.month]}°<small>C</small></strong><span>Daytime high</span></div><div><strong>${rec.lo[state.month]}°<small>C</small></strong><span>Nighttime low</span></div><div><strong>${rec.pr[state.month]}<small> mm</small></strong><span>Monthly rain</span></div></div>`;}
function destinationHTML(){const rec=selected(),c=climate(),theme=THEMES[state.theme];const f=data.features.find(f=>f.iso===rec.iso);return `<div class="destination-art">${rec.iso===124?`<img class="destination-photo" data-travel-image src="${theme.image}" alt="${state.theme==='atlas'?'Moraine Lake and mountains in Alberta':'Illustrated alpine lake and mountains in the Canadian Rockies'}"><span class="photo-label">${theme.imageLabel}</span>`:`<div class="destination-abstract">${f?`<svg data-country-outline="${rec.iso}" aria-label="Outline of ${esc(rec.name)}"><path d="${f.d}"/></svg>`:`<span class="eyebrow">${esc(rec.region)}</span>`}</div>`}</div><div class="destination-body"><p class="eyebrow">${rec.iso===124?'NORTH AMERICA':esc(rec.region)} <b>/</b> ${MONTHS[state.month]}</p><div class="country-heading"><h2>${esc(rec.name)}</h2><span class="country-number">${String(rec.iso).padStart(3,'0')}</span></div><p class="country-caption">${rec.iso===124?'A little wild. A lot to discover.':`Seasons in ${esc(rec.city)}`}</p><div class="rating-line"><span class="rating-value">${c.score}<small>/ 100</small></span><span class="rating-pill">${swatch(c.band.key)}${c.band.label} weather</span></div>${statsHTML(rec)}<div class="mini-chart" aria-label="Weather comfort by month">${rec.months.map((c,i)=>`<button data-mini-month="${i}" class="${i===state.month?'active':''}" style="--bar:${color(c.band.key)};--height:${Math.max(10,c.score)}%" aria-label="${MONTHS[i]}: ${c.score} out of 100" aria-pressed="${i===state.month}"></button>`).join('')}</div><div class="chart-caption"><span>JAN</span><span>THE YEAR AT A GLANCE</span><span>DEC</span></div>${rec.iso===124?'<a class="button" href="#canada">Explore Canada <span>↗</span></a>':rec.slug?`<a class="button" href="https://gowhereandwhen.com/country/${rec.slug}/" target="_blank" rel="noopener">Country guide <span>↗</span></a>`:'<a class="button secondary" href="#canada">Explore the Canada guide <span>↗</span></a>'}<p class="data-note">Based on ${esc(rec.city)} climate averages. Conditions vary across the country.${c.tags.length?`<br>${c.tags.map(t=>esc(t.label)).join(' · ')}.`:''}</p></div>`;}
function mapHTML(){const theme=THEMES[state.theme];return `<div class="map-page"><div class="map-heading"><div><p class="eyebrow"><b>↗</b>${theme.eyebrow}</p><h1>${theme.heading}</h1><p>${theme.sub}</p></div><form class="search-form" role="search"><div class="search-field"><svg viewBox="0 0 24 24" aria-hidden="true"><circle cx="10.5" cy="10.5" r="6.5"/><path d="m16 16 5 5"/></svg><input id="country-search" type="search" placeholder="Where are you dreaming of?" aria-label="Search countries or cities" autocomplete="off" aria-controls="search-results"></div><div id="search-results" class="search-results"></div></form></div><div class="map-layout"><div class="map-main"><div class="map-surface ${state.tilt?'':'flat'}"><div class="surface-top"><span>${theme.mapLabel}</span><div class="view-switch" aria-label="Map display"><button data-view="map" aria-pressed="${state.view==='map'}">Map</button><button data-view="grid" aria-pressed="${state.view==='grid'}">Grid</button></div></div>${worldSVG()}<div class="grid-scroll" ${state.view==='grid'?'':'hidden'}><table class="country-grid"><thead><tr><th>Country</th>${SHORT.map(m=>`<th>${m}</th>`).join('')}</tr></thead><tbody id="country-grid-body">${state.view==='grid'?gridRows():''}</tbody></table></div><div class="map-controls" ${state.view==='grid'?'hidden':''}><button data-zoom="in" aria-label="Zoom in">+</button><button data-zoom="out" aria-label="Zoom out">−</button><button data-zoom="reset" aria-label="Reset map zoom">↺</button>${state.theme==='explorer'?`<button id="tilt-button" aria-pressed="${state.tilt}">${state.tilt?'3D view':'Flat view'}</button>`:''}</div><div class="map-compass" aria-hidden="true">N${compass}</div><div class="map-tooltip" hidden></div></div>${timelineHTML()}${legendHTML()}</div><aside id="destination" class="destination-panel" aria-label="Selected destination">${destinationHTML()}</aside></div></div>`;}
function worldSVG(){let lines='';for(let lon=-180;lon<=180;lon+=30){const [x]=project(lon,0);lines+=`M${x},0V540`;}for(let lat=-60;lat<=90;lat+=30){const [,y]=project(0,lat);lines+=`M0,${y}H1200`;}
 const labels=[[124,'CANADA',-103,60],[840,'UNITED STATES',-103,38],[76,'BRAZIL',-53,-10],[32,'ARGENTINA',-64,-34],[643,'RUSSIA',95,60],[156,'CHINA',104,35],[356,'INDIA',79,23],[36,'AUSTRALIA',134,-24],[710,'SOUTH AFRICA',25,-28],[12,'ALGERIA',2,28],[250,'FRANCE',2,46],[392,'JAPAN',139,37],[304,'GREENLAND',-42,74]].map(([iso,name,lon,lat])=>{const [x,y]=project(lon,lat);return `<text class="map-label" x="${x}" y="${y}">${name}</text>`;}).join('');
 const paths=data.features.map(f=>`<path class="country ${f.iso===state.iso?'selected':''}" data-iso="${f.iso}" d="${f.d}" fill="${byIso.has(f.iso)?color(byIso.get(f.iso).months[state.month].band.key):'var(--line)'}" ${byIso.has(f.iso)?`tabindex="0" role="button" aria-label="${esc(f.name)}"`:'aria-hidden="true"'}/>`).join('');
 const depths=[9,6,3].map(depth=>`<g transform="translate(0 ${depth})">${data.features.map(f=>`<path d="${f.d}"/>`).join('')}</g>`).join('');
 return `<svg id="world-map" class="world-map" viewBox="${mapBox.x} ${mapBox.y} ${mapBox.w} ${mapBox.h}" preserveAspectRatio="xMidYMid meet" ${state.view==='grid'?'hidden':''} aria-label="World map. Select a country, drag to pan, or use the zoom buttons."><defs><clipPath id="map-clip"><rect x="0" y="0" width="1200" height="540"/></clipPath></defs><g class="map-scene" clip-path="url(#map-clip)"><path class="graticule" d="${lines}"/><text class="ocean-label" x="165" y="290">Pacific Ocean</text><text class="ocean-label" x="440" y="247">Atlantic Ocean</text><text class="ocean-label" x="863" y="390">Indian Ocean</text><g class="land-depth" aria-hidden="true">${depths}</g><g class="countries">${paths}</g><g class="map-labels" aria-hidden="true">${labels}</g><g id="map-pin" class="pin" aria-hidden="true"></g></g></svg>`;}
function paintMap(){$$('.country').forEach(p=>{const rec=byIso.get(+p.dataset.iso);if(!rec)return;const c=rec.months[state.month];p.style.fill=color(c.band.key);p.classList.toggle('selected',rec.iso===state.iso);p.setAttribute('aria-label',`${rec.name}: ${c.band.label}, ${c.score} out of 100. Select country.`);p.setAttribute('aria-pressed',String(rec.iso===state.iso));});const positions={124:[-98,57],840:[-99,38],392:[137,37],250:[2,46],36:[134,-25],156:[103,35],356:[79,23],76:[-53,-10],826:[-3,55],276:[10,51],710:[25,-29]};const rec=selected();const f=data.features.find(f=>f.iso===rec.iso);let xy=positions[rec.iso]?project(...positions[rec.iso]):null;if(!xy&&f){const p=$(`.country[data-iso="${rec.iso}"]`);const b=p.getBBox();xy=[b.x+b.width/2,b.y+b.height/2];}$('#map-pin').innerHTML=xy?`<circle cx="${xy[0]}" cy="${xy[1]}" r="5"/><circle cx="${xy[0]}" cy="${xy[1]}" r="10" style="fill:none;opacity:.4;stroke:var(--accent)"/>`:'';}
function gridRows(){return [...data.countries].sort((a,b)=>a.name.localeCompare(b.name)).map(rec=>`<tr><td><button data-grid-country="${rec.iso}">${esc(rec.name)}</button></td>${rec.months.map((c,m)=>`<td><button class="grid-score ${m===state.month&&rec.iso===state.iso?'current':''}" data-grid-country="${rec.iso}" data-grid-month="${m}" style="--bar:${color(c.band.key)}" aria-label="${esc(rec.name)}, ${MONTHS[m]}: ${c.score}, ${c.band.label}">${c.score}</button></td>`).join('')}</tr>`).join('');}
function fitOutline(svg){const path=$('path',svg);if(!path)return;const b=path.getBBox();if(b.width&&b.height)svg.setAttribute('viewBox',`${b.x-8} ${b.y-8} ${b.width+16} ${b.height+16}`);}
function wireDestination(){$$('[data-mini-month]').forEach(b=>b.addEventListener('click',()=>setMonth(+b.dataset.miniMonth)));$$('[data-country-outline]').forEach(fitOutline);}
function wireMap(){paintMap();wireDestination();$$('.month-buttons button').forEach(b=>b.addEventListener('click',()=>setMonth(+b.dataset.month)));$$('[data-view]').forEach(b=>b.addEventListener('click',()=>{state.view=b.dataset.view;render();}));$('#tilt-button')?.addEventListener('click',()=>{state.tilt=!state.tilt;$('.map-surface').classList.toggle('flat',!state.tilt);$('#tilt-button').textContent=state.tilt?'3D view':'Flat view';$('#tilt-button').setAttribute('aria-pressed',String(state.tilt));});
 const search=$('#country-search'),results=$('#search-results');
 const matches=()=>{const q=search.value.trim().toLowerCase();return q?data.countries.filter(c=>`${c.name} ${c.city}`.toLowerCase().includes(q)).slice(0,8):[];};
 search.addEventListener('input',()=>{const found=matches();results.innerHTML=found.length?found.map(rec=>`<button type="button" data-search-iso="${rec.iso}"><span>${esc(rec.name)}</span><small>${esc(rec.city)}</small></button>`).join(''):search.value.trim()?'<p>No destinations found.</p>':'';});
 search.addEventListener('keydown',e=>{if(e.key==='Escape'){results.innerHTML='';search.value='';}if(e.key==='ArrowDown'){const first=$('button',results);if(first){e.preventDefault();first.focus();}}});
 results.addEventListener('click',e=>{const b=e.target.closest('[data-search-iso]');if(!b)return;setCountry(+b.dataset.searchIso);search.value=selected().name;results.innerHTML='';search.focus();});
 $('.search-form').addEventListener('submit',e=>{e.preventDefault();const first=matches()[0];if(first){setCountry(first.iso);search.value=first.name;results.innerHTML='';}});
 $('.grid-scroll').addEventListener('click',e=>{const b=e.target.closest('[data-grid-country]');if(!b)return;setCountry(+b.dataset.gridCountry);if(b.hasAttribute('data-grid-month'))setMonth(+b.dataset.gridMonth);});
 const svg=$('#world-map');let drag=null,moved=false;const points=new Map();let pinch=null;
 function applyBox(){svg.setAttribute('viewBox',`${mapBox.x} ${mapBox.y} ${mapBox.w} ${mapBox.h}`);}
 function zoom(factor){const nw=Math.max(200,Math.min(1500,mapBox.w*factor));const ratio=nw/mapBox.w;mapBox={x:mapBox.x+(mapBox.w-nw)/2,y:mapBox.y+(mapBox.h-mapBox.h*ratio)/2,w:nw,h:mapBox.h*ratio};applyBox();}
 $$('[data-zoom]').forEach(b=>b.addEventListener('click',()=>{if(b.dataset.zoom==='reset'){mapBox={x:0,y:10,w:1200,h:530};applyBox();}else zoom(b.dataset.zoom==='in'?.75:1.33);}));
 svg.addEventListener('wheel',e=>{if(e.ctrlKey||e.metaKey){e.preventDefault();zoom(e.deltaY>0?1.08:.92);}}, {passive:false});
 svg.addEventListener('pointerdown',e=>{points.set(e.pointerId,{x:e.clientX,y:e.clientY});moved=false;drag={id:e.pointerId,x:e.clientX,y:e.clientY,box:{...mapBox}};if(points.size===2){const p=[...points.values()];pinch={distance:Math.hypot(p[0].x-p[1].x,p[0].y-p[1].y),box:{...mapBox}};}svg.setPointerCapture(e.pointerId);});
 svg.addEventListener('pointermove',e=>{if(points.has(e.pointerId))points.set(e.pointerId,{x:e.clientX,y:e.clientY});if(points.size===2&&pinch){const p=[...points.values()];const distance=Math.hypot(p[0].x-p[1].x,p[0].y-p[1].y);mapBox={...pinch.box};zoom(pinch.distance/Math.max(1,distance));moved=true;return;}if(!drag)return;const dx=e.clientX-drag.x,dy=e.clientY-drag.y;if(Math.hypot(dx,dy)>4)moved=true;if(!moved)return;svg.classList.add('dragging');const unit=Math.max(drag.box.w/svg.clientWidth,drag.box.h/svg.clientHeight);mapBox.x=Math.max(-400,Math.min(1200,drag.box.x-dx*unit));mapBox.y=Math.max(-220,Math.min(530,drag.box.y-dy*unit));applyBox();$('.map-tooltip').hidden=true;});
 svg.addEventListener('pointerup',e=>{const wasClick=!moved&&points.size===1;points.delete(e.pointerId);if(svg.hasPointerCapture(e.pointerId))svg.releasePointerCapture(e.pointerId);if(wasClick){const hit=document.elementFromPoint(e.clientX,e.clientY)?.closest('.country');if(hit)setCountry(+hit.dataset.iso);}drag=null;pinch=null;svg.classList.remove('dragging');});
 svg.addEventListener('pointercancel',e=>{points.delete(e.pointerId);drag=null;pinch=null;svg.classList.remove('dragging');});
 $$('.country').forEach(p=>{p.addEventListener('keydown',e=>{if(e.key==='Enter'||e.key===' '){e.preventDefault();setCountry(+p.dataset.iso);}});p.addEventListener('pointermove',e=>{if(drag||e.pointerType==='touch')return;const rec=byIso.get(+p.dataset.iso);if(!rec)return;const tip=$('.map-tooltip'),bounds=$('.map-surface').getBoundingClientRect(),c=rec.months[state.month];tip.innerHTML=`<strong>${esc(rec.name)}</strong>${MONTHS[state.month]} · ${c.band.label} · ${c.score}/100`;tip.hidden=false;tip.style.left=`${Math.max(8,Math.min(bounds.width-190,e.clientX-bounds.left+14))}px`;tip.style.top=`${Math.max(8,Math.min(bounds.height-65,e.clientY-bounds.top+14))}px`;});p.addEventListener('pointerleave',()=>$('.map-tooltip').hidden=true);});
}
function monthDetailHTML(){const rec=byIso.get(124),c=rec.months[state.month];const descriptions=rec.hi[state.month]<8?'Cold days and colder nights. Come prepared for winter conditions.':rec.hi[state.month]<18?'Cool days and changing conditions. Pack layers for exploring.':'Warm days and plenty of possibilities. A good season to spend outside.';return `<p class="eyebrow">YOUR MONTH IN CANADA</p><h3>${MONTHS[state.month]}</h3><div class="rating-line"><span class="rating-value">${c.score}<small>/ 100</small></span><span class="rating-pill">${swatch(c.band.key)}${c.band.label}</span></div>${statsHTML(rec)}<p class="month-description">${descriptions}</p>${c.tags.length?`<p class="tags">${c.tags.map(t=>esc(t.label)).join(' · ')}</p>`:''}`;}
function canadaMapHTML(){const f=data.features.find(f=>f.iso===124);return `<div class="canada-outline"><svg id="canada-outline" viewBox="95 12 350 155" role="img" aria-label="Canada, with Vancouver and Toronto marked"><path d="${f.d}"/>${[[-123.12,49.28,'Vancouver',-60,16],[-79.38,43.65,'Toronto',7,15]].map(([lon,lat,label,dx,dy])=>{const [x,y]=project(lon,lat);return `<circle cx="${x}" cy="${y}" r="3"/><text x="${x+dx}" y="${y+dy}">${label}</text>`;}).join('')}</svg><p>ONE COUNTRY. MANY CLIMATES.</p></div>`;}
function guideHTML(){const rec=byIso.get(124),copy=data.canada,theme=THEMES[state.theme];return `<article class="guide-page"><div class="guide-breadcrumb"><a href="#map">← Back to the world</a><span>THE AMERICAS / CANADA / COUNTRY GUIDE</span></div><section class="guide-cover"><div class="guide-cover-copy"><p class="eyebrow">NORTH AMERICA <b> / </b> THE GREAT OUTDOORS</p><h1>Canada</h1><p class="guide-deck">${theme.canadaDeck}</p><p class="guide-lead">${copy.heroLead}</p><a class="button" href="#year">Find your best month <span>↓</span></a></div><figure class="guide-picture"><img data-travel-image src="${theme.image}" alt="${state.theme==='atlas'?'Clear water reflecting the Canadian Rockies at Moraine Lake':'An illustrated alpine lake among mountains in the Canadian Rockies'}"><figcaption>${state.theme==='atlas'?`<a href="https://commons.wikimedia.org/wiki/File:Calm_waters_between_mountains_(Unsplash).jpg" target="_blank" rel="noopener">${theme.imageCredit}</a>`:theme.imageCredit}</figcaption></figure><span class="guide-cover-badge">Your ticket to<strong>the great outdoors</strong></span></section><div class="guide-overview"><div class="overview-item"><span>↗</span><div><small>THE CLASSIC TRIP</small><strong>June to August</strong><p>Warm days, long light, open roads.</p></div></div><div class="overview-item"><span>◌</span><div><small>A QUIETER SEASON</small><strong>September & October</strong><p>Autumn colour and fewer crowds.</p></div></div><div class="overview-item"><span>✳</span><div><small>WINTER, ON PURPOSE</small><strong>December to March</strong><p>Snow, ski slopes and northern lights.</p></div></div></div><section class="guide-section" id="year"><div class="section-heading"><div><p class="eyebrow"><b>01</b> FIND YOUR SEASON</p><h2>A year of possibilities.</h2></div><p>Select a month to explore the weather. Ratings are based on Toronto.</p></div><div class="year-explorer"><div><div id="year-chart" class="year-chart" aria-label="Canada weather comfort by month">${rec.months.map((c,m)=>`<button class="year-column ${m===state.month?'active':''}" data-month="${m}" aria-label="${MONTHS[m]}: ${c.score} out of 100, ${c.band.label}" aria-pressed="${m===state.month}"><strong>${c.score}</strong><span class="year-bar" style="--bar:${color(c.band.key)};--height:${c.score*1.35}px"></span><span class="year-label">${SHORT[m]}</span></button>`).join('')}</div><p class="year-chart-note">Weather comfort, out of 100. Higher is better. Winter activities can be excellent even when the comfort score is low.</p>${legendHTML()}</div><div id="month-detail" class="month-detail" aria-live="polite">${monthDetailHTML()}</div></div></section><section class="guide-section"><div class="section-heading"><div><p class="eyebrow"><b>02</b> A CLOSER LOOK</p><h2>One country. Many seasons.</h2></div><p>Where you go changes when you go.</p></div><div class="regions-layout">${canadaMapHTML()}<div class="region-list">${copy.regions.map((r,i)=>`<div class="region-row"><span>0${i+1}</span><div><h3>${r.h}</h3><p>${r.p}</p></div></div>`).join('')}</div></div></section><section class="guide-section"><div class="section-heading"><div><p class="eyebrow"><b>03</b> WHAT BRINGS YOU HERE?</p><h2>A season for your kind of trip.</h2></div></div><div class="activities">${copy.bestFor.map((r,i)=>`<div class="activity"><span class="activity-no">0${i+1} / CANADA</span><h3>${r.h}</h3><p>${r.p}</p></div>`).join('')}</div></section><div class="guide-bottom"><section class="guide-section events"><div class="section-heading"><div><p class="eyebrow"><b>04</b> MARK YOUR CALENDAR</p><h2>Worth going for.</h2></div></div>${copy.whatsOn.map(e=>`<h3>${e.h}</h3><p>${e.p}</p>`).join('')}</section><section class="guide-section"><div class="section-heading"><div><p class="eyebrow"><b>05</b> BEFORE YOU GO</p><h2>Good to know.</h2></div></div>${copy.faq.map(f=>`<details><summary>${f.q}</summary><p>${f.a}</p></details>`).join('')}</section></div><div class="guide-return"><p>Weather ratings use long-run averages for Toronto. They are a planning guide, not a forecast or a whole-country average.</p><a class="button secondary" href="#map">Keep exploring the world <span>↗</span></a></div></article>`;}
function wireGuide(){$$('#year-chart button').forEach(b=>b.addEventListener('click',()=>setMonth(+b.dataset.month)));}
$$('.design-options button').forEach(b=>b.addEventListener('click',()=>{if(data)setTheme(b.dataset.theme);}));
document.addEventListener('click',e=>{const a=e.target.closest('a');if(!a)return;const href=a.getAttribute('href');if(href==='#map'||href==='#canada'){e.preventDefault();if(!data)return;state.page=href==='#canada'?'canada':'map';if(state.page==='canada')state.iso=124;render();window.scrollTo({top:0,behavior:'instant'});}else if(href==='#year'){e.preventDefault();$('#year')?.scrollIntoView({behavior:matchMedia('(prefers-reduced-motion: reduce)').matches?'instant':'smooth'});}});
window.addEventListener('popstate',()=>{if(!data)return;const p=new URLSearchParams(location.search);if(THEMES[p.get('theme')])state.theme=p.get('theme');state.page=location.hash==='#canada'?'canada':'map';state.month=p.has('month')?Math.max(0,Math.min(11,(Number(p.get('month'))||1)-1)):6;state.iso=byIso.has(Number(p.get('country')))?Number(p.get('country')):124;render();});
async function start(){try{const response=await fetch('./data.json');if(!response.ok)throw new Error('Data unavailable');data=await response.json();byIso=new Map(data.countries.map(c=>[c.iso,c]));if(!byIso.has(state.iso))state.iso=124;if(state.page==='canada')state.iso=124;render();}catch(error){$('#app').innerHTML='<div class="startup"><h1>The atlas could not load.</h1><p>Please reload to try again.</p><button class="button" id="retry">Try again ↗</button></div>';$('#retry').addEventListener('click',start);console.error(error);}}
start();
